using Godot;
using System;
using System.Linq;
using System.Collections.Generic;
using Settings=Godot.Collections.Dictionary;
public partial class ActorInspectorOperations
{
    public Variant animated_object_value(Control owner,Resource actor,Resource data,Resource definition,Resource property)
    {
        var basis=_definitions.value_for(data,property);var path=_timeline.object_animation_path(actor,data,property.Get("id").AsStringName());var model=Ui<RefCounted>(owner,"model");var clip=_timeline.clip_for_actor_id(model,actor.Get("id").AsString());if(clip==null||path.Length==0)return basis;double time=_clips.local_time(clip,model.Get("playhead_time").AsDouble());if(property.Get("id").AsString()=="uniforms"&&basis.VariantType==Variant.Type.Dictionary){var uniforms=basis.AsGodotDictionary().Duplicate();foreach(var value in actor.Get("animation_tracks").AsGodotArray()){var track=value.As<Resource>();var address=track.Get("path").AsStringArray();if(address.Length==path.Length+1&&address.Take(path.Length).SequenceEqual(path))uniforms[new StringName(address[^1])]=_animation.sampled_value(actor,address,time,default);}return uniforms;}return _animation.sampled_value(actor,path,time,basis);
    }
    public void add_object_value(Control owner,Resource actor,Resource data,Resource definition,Resource property,VBoxContainer parent)
    {
        if(owner.Call("_add_special_object_value",actor,data,definition,property,parent).AsBool())return;Variant Current()=>animated_object_value(owner,actor,data,definition,property);var current=Current();var options=property.Get("options").AsGodotDictionary();var key=property.Get("id").AsStringName();var model=Ui<RefCounted>(owner,"model");void Edit(Variant value)=>_timeline.edit_object_property(model,actor,data,definition,key,value);void Preview(Variant value)=>_timeline.preview_object_property(model,actor,data,definition,key,value);void Finish(Variant original,Variant value)=>_timeline.commit_object_property_preview(model,actor,data,definition,key,original,value);var heading=new HBoxContainer();parent.AddChild(heading);heading.AddChild(new Label{Text=property.Get("label").AsString(),SizeFlagsHorizontal=Control.SizeFlags.ExpandFill,TextOverrunBehavior=TextServer.OverrunBehavior.TrimEllipsis,TooltipText=options.GetValueOrDefault("tooltip",property.Get("label")).AsString()});var path=_animation.path_to_object(actor,data);if(path.Length>0)add_keyframe_button(owner,heading,actor,property,path.Append(key.ToString()).ToArray(),default);var reset=new Button{Name=key+"_reset",Text="↺",Visible=!same_value(current,_properties.create_default(property))};heading.AddChild(reset);reset.Pressed+=()=>{Edit(_properties.create_default(property));if(options.GetValueOrDefault("refresh_inspector",false).AsBool())owner.CallDeferred("_rebuild_selected");};var updaters=owner.Get("_updaters").AsGodotArray();updaters.Add(Callable.From(()=>reset.Visible=!same_value(Current(),_properties.create_default(property))));if(options.ContainsKey("choices")){var choice=choice_editor(parent,property,current.AsInt32());choice.ItemSelected+=index=>{Edit(index);if(options.GetValueOrDefault("refresh_inspector",false).AsBool())owner.CallDeferred("_rebuild_selected");};updaters.Add(Callable.From(()=>choice.Select(Current().AsInt32())));return;}
        void Wire(SpinBox input,Func<double,Variant> make){Variant origin=current;input.Connect("interaction_started",Callable.From(()=>origin=_data.copy_value(Current())));input.Connect("preview_changed",Callable.From<double>(n=>Preview(make(n))));input.Connect("drag_committed",Callable.From<double>(n=>Finish(origin,make(n))));input.Connect("drag_cancelled",Callable.From(()=>Preview(origin)));input.ValueChanged+=n=>Edit(make(n));}
        switch((Variant.Type)property.Get("value_type").AsInt32()){
        case Variant.Type.Float:case Variant.Type.Int:var numeric=number_editor(owner,parent,current.AsDouble(),property);Wire(numeric,n=>property.Get("value_type").AsInt32()==(int)Variant.Type.Int?Variant.From((long)n):Variant.From(n));updaters.Add(Callable.From(()=>set_number_silent(numeric,Current().AsDouble())));break;
        case Variant.Type.Vector2:case Variant.Type.Vector3:int count=property.Get("value_type").AsInt32()==(int)Variant.Type.Vector2?2:3;StringName linkKey="Object:"+definition.Get("type_id").AsString()+":"+key;var state=Ui<Resource>(owner,"ui_state");string id=actor.Get("id").AsString();var link=new Button{Text="🔗",ToggleMode=true,ButtonPressed=_state.vector_linked(state,id,linkKey),TooltipText="Link components: changing one sets all to the same value"};heading.AddChild(link);link.Toggled+=enabled=>_state.set_vector_linked(state,id,linkKey,enabled);for(int i=0;i<count;i++){int axis=i;var row=new HBoxContainer();parent.AddChild(row);row.AddChild(new Label{Text=new[]{"X","Y","Z"}[axis],Modulate=new Color(new[]{"ee9e9e","9ed8b5","99bce8"}[axis])});var input=number(owner,ActorAnimationOperations.Component(current,axis).AsDouble(),options.GetValueOrDefault("step",.01).AsDouble());input.Name=key+"_"+axis;row.AddChild(input);Wire(input,n=>{var next=_data.copy_value(Current());if(link.ButtonPressed){for(int component=0;component<count;component++)next=ActorAnimationOperations.WithComponent(next,component,n);}else next=ActorAnimationOperations.WithComponent(next,axis,n);return next;});updaters.Add(Callable.From(()=>input.SetValueNoSignal(ActorAnimationOperations.Component(Current(),axis).AsDouble())));}break;
        case Variant.Type.String:case Variant.Type.StringName:if(options.GetValueOrDefault("file_picker",false).AsBool()){owner.Call("_add_object_file_slot",actor,data,definition,property,parent);break;}var text=new LineEdit{Name=key+"_text",Text=current.ToString(),SizeFlagsHorizontal=Control.SizeFlags.ExpandFill,Editable=!options.GetValueOrDefault("read_only",false).AsBool()};parent.AddChild(text);void Submit()=>Edit(property.Get("value_type").AsInt32()==(int)Variant.Type.StringName?Variant.From(new StringName(text.Text)):Variant.From(text.Text));text.TextSubmitted+=_=>Submit();text.FocusExited+=Submit;updaters.Add(Callable.From(()=>{if(!text.HasFocus())text.Text=Current().ToString();}));break;
        case Variant.Type.Bool:var toggle=new CheckButton{Name=key.ToString(),ButtonPressed=current.AsBool()};parent.AddChild(toggle);toggle.Toggled+=value=>{Edit(value);if(options.GetValueOrDefault("refresh_inspector",false).AsBool())owner.Call("_queue_rebuild_selected");};updaters.Add(Callable.From(()=>toggle.SetPressedNoSignal(Current().AsBool())));break;
        case Variant.Type.Color:var color=new LiveColorPickerButton();color.Name=key.ToString();color.Color=current.AsColor();parent.AddChild(color);color.Connect("interaction_started",Callable.From(()=>Hint(owner,color,"Esc cancels color drag")));color.Connect("interaction_ended",Callable.From(()=>Hint(owner,color,"")));color.Connect("preview_changed",Callable.From<Color>(value=>Preview(value)));color.Connect("drag_committed",Callable.From<Color,Color>((original,value)=>Finish(original,value)));color.Connect("drag_cancelled",Callable.From<Color>(original=>Preview(original)));updaters.Add(Callable.From(()=>color.Call("set_color_silent",Current())));break;}
    }
}
